### Python

```python
import sys


def solve(a, b):
    # 计算所有位置对最终分差 A-B 的总贡献
    ans = 0
    for i in range(len(a)):
        ans += a[i] - b[i]
    return ans


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # 第一位是测试组数
    t = int(data[0])
    idx = 1
    res = []

    for _ in range(t):
        # 读入当前测试用例的 n
        n = int(data[idx])
        idx += 1

        # 读入数组 a
        a = list(map(int, data[idx:idx + n]))
        idx += n

        # 读入数组 b
        b = list(map(int, data[idx:idx + n]))
        idx += n

        # 调用外部函数计算答案
        res.append(str(solve(a, b)))

    print("\n".join(res))


if __name__ == "__main__":
    main()
```

### Java

```java
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    public static long solve(int[] a, int[] b) {
        // 计算所有位置对最终分差 A-B 的总贡献
        long ans = 0;
        for (int i = 0; i < a.length; i++) {
            ans += (long) a[i] - b[i];
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // 读入测试组数
        int t = sc.nextInt();
        List<Long> list = new ArrayList<>();

        while (t-- > 0) {
            // 读入当前测试用例的 n
            int n = sc.nextInt();

            // 读入数组 a
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = sc.nextInt();
            }

            // 读入数组 b
            int[] b = new int[n];
            for (int i = 0; i < n; i++) {
                b[i] = sc.nextInt();
            }

            // 调用外部函数计算答案
            list.add(solve(a, b));
        }

        // 按行输出所有答案
        StringBuilder sb = new StringBuilder();
        for (long ans : list) {
            sb.append(ans).append('\n');
        }
        System.out.print(sb.toString());
    }
}
